import heapq

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)

    def dijkstra(graph, start):
        queue = [(0, start)]
        visited = {start: 0}
        parent = {start: None}
        while queue:
            cost, current = heapq.heappop(queue)
            if cost > visited[current]:
                continue
            for neighbor, weight in graph[current]:
                distance = cost + weight
                if neighbor not in visited or distance < visited[neighbor]:
                    visited[neighbor] = distance
                    parent[neighbor] = current
                    heapq.heappush(queue, (distance, neighbor))
        return (parent, visited)
    parent, dist = dijkstra(graph, source)
    if target not in dist:
        return (float('inf'), None)
    path = []
    node = target
    while node:
        path.append(node)
        node = parent[node]
    path.reverse()
    return (dist[target], path)

from collections import deque

def shortest_path(graph, source, target):
    distance = {}
    predecessor = {}
    seen = {}
    queue = deque()
    for vertex in graph:
        distance[vertex] = float('inf')
        predecessor[vertex] = None
        seen[vertex] = False
    distance[source] = 0
    queue.append(source)
    seen[source] = True
    while len(queue) > 0:
        current = queue.popleft()
        for neighbour, weight in graph[current]:
            if not seen[neighbour]:
                seen[neighbour] = True
                queue.append(neighbour)
                distance[neighbour] = distance[current] + weight
                predecessor[neighbour] = current
    path = deque([])
    current = target
    while predecessor[current] is not None:
        path.appendleft(current)
        current = predecessor[current]
    if current is not None:
        path.appendleft(current)
    if len(path) > 0:
        return (distance[target], path)
    else:
        return (float('inf'), None)
